+test("cooking and consumption use batches FEFO (earliest expiry first, null last, then receivedOn and id)", () => {
+  const store = fresh();
+  const used = cook(store, 2, 10, { at });
+  const milkUsed = used.find((u) => u.itemId === 2);
+  assert.deepEqual(milkUsed.batches, [{ batchId: 4, qty: 2 }]);
+  assert.equal(getBatch(store, 4).qty, 0);
+  assert.equal(getBatch(store, 3).qty, 8);
