+  // Tie-breakers: no expiry last, same expiry -> earlier receivedOn -> lower id
+  store.data.batches.push(
+    { id: 10, itemId: 2, lot: "HD-NOEXP", qty: 5, receivedOn: "2026-10-01", expires: null, location: "fridge" },
