+    { id: 12, itemId: 2, lot: "HD-SAME-1", qty: 4, receivedOn: "2026-10-20", expires: "2026-11-02", location: "fridge" },
+  );
+  const more = consume(store, 2, 16, { at, ref: "fefo" });
+  assert.deepEqual(more, [
+    { batchId: 12, qty: 4 },
+    { batchId: 3, qty: 8 },
